public class TokenCounter{private final int[]buffer=new int[5];private int count=0,in=0,out=0;public synchronized void put(int token)throws InterruptedException{while(count==buffer.length)wait();buffer[in]=token;in=(in+1)%buffer.length;count++;notifyAll();}public synchronized int take()throws InterruptedException{while(count==0)wait();int token=buffer[out];out=(out+1)%buffer.length;count--;notifyAll();return token;}public static void main(String[]x)throws InterruptedException{TokenCounter c=new TokenCounter();int[]sum=new int[2];Thread cook=new Thread(()->{try{for(int t=1;t<=20;t++)c.put(t);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread[]s=new Thread[2];for(int i=0;i<2;i++){final int id=i;s[i]=new Thread(()->{try{for(int k=0;k<10;k++)sum[id]+=c.take();}catch(InterruptedException e){Thread.currentThread().interrupt();}});}cook.start();for(Thread t:s)t.start();cook.join();for(Thread t:s)t.join();System.out.println("Sum of tokens collected: "+(sum[0]+sum[1])+" (expected 210)");}}